<?php foreach ($utilisateurs as $user): $displayName = trim($user['nom_utilisateur']) ?: $user['matricule']; $encoded = htmlspecialchars(json_encode(['id'=>(int)$user['id'],'nom_utilisateur'=>$displayName,'role'=>$user['role'],'profil'=>$user['profil']]), ENT_QUOTES, 'UTF-8'); ?><tr data-search="<?= htmlspecialchars(strtolower($displayName.' '.$user['matricule'].' '.$user['role'])) ?>"><td><div class="identity"><span><?php if ($user['profil']): ?><img src="<?= BASE_URL . '/' . htmlspecialchars($user['profil']) ?>" alt="Profil"><?php else: ?><?= htmlspecialchars(strtoupper(substr($displayName,0,2))) ?><?php endif; ?></span><div><strong><?= htmlspecialchars($displayName) ?></strong><small><?= htmlspecialchars($user['matricule']) ?></small></div></div></td><td><span class="role-badge role-<?= strtolower($user['role']) ?>"><?= htmlspecialchars($user['role']) ?></span></td><td><?= $user['derniere_connexion'] ? date('d/m/Y H:i', strtotime($user['derniere_connexion'])) : '<span class="muted">Jamais</span>' ?></td><td><?= date('d/m/Y', strtotime($user['created_at'])) ?></td><td><span class="active-badge"><i></i> Actif</span></td><td><div class="row-actions"><button onclick="openUserModal(<?= $encoded ?>)" title="Modifier"><i class="bi bi-pencil"></i></button><?php if ((int)$user['id'] !== $currentId): ?><button class="danger" onclick="openDeleteModal(<?= (int)$user['id'] ?>,'<?= htmlspecialchars($displayName, ENT_QUOTES) ?>')" title="Désactiver"><i class="bi bi-trash3"></i></button><?php endif; ?></div></td></tr><?php endforeach; ?>
</tbody></table></div></section>
<section class="users-table-card view-panel hidden" id="roles-view"><div class="users-table-scroll"><table><thead><tr><th>Rôle</th><th>Description</th><th>Utilisateurs</th></tr></thead><tbody><?php foreach (['ADMIN'=>'Accès complet et administration','CEO'=>'Consultation stratégique et rapports','COMPTABLE'=>'Gestion des opérations financières'] as $code=>$description): $count=count(array_filter($utilisateurs,fn($u)=>$u['role']===$code)); ?><tr data-search="<?= strtolower($code.' '.$description) ?>"><td><span class="role-badge role-<?= strtolower($code) ?>"><?= $code ?></span></td><td><?= $description ?></td><td><strong><?= $count ?></strong> utilisateur(s)</td></tr><?php endforeach; ?></tbody></table></div></section>
