<div class="users-modal-overlay" id="user-modal"><div class="users-modal"><div class="modal-title"><div><h3 id="user-modal-title">Ajouter un utilisateur</h3><p id="user-modal-subtitle">Créer un nouveau compte d’accès</p></div><button onclick="closeModal('user-modal')">&times;</button></div><form method="POST" enctype="multipart/form-data" action="<?= BASE_URL ?>/utilisateurs"><input type="hidden" name="action" id="user-action" value="create"><input type="hidden" name="id" id="user-id"><label class="profile-upload"><span class="profile-preview" id="profile-preview"><i class="bi bi-camera"></i></span><span>Photo de profil<small>JPG, PNG ou WEBP · 2 Mo maximum</small></span><input type="file" name="profil" id="user-profile" accept="image/jpeg,image/png,image/webp" onchange="previewProfile(this)"></label><label>Nom de l’utilisateur<input name="nom_utilisateur" id="user-name" required maxlength="100" placeholder="Nom complet"></label><label>Rôle<select name="role" id="user-role" required><option value="ADMIN">Administrateur</option><option value="CEO">CEO</option><option value="COMPTABLE">Comptable</option></select><small>Le matricule sera généré automatiquement selon le rôle et l’année.</small></label><label>Mot de passe<input type="password" name="mot_de_passe" id="user-password" minlength="4" placeholder="Minimum 4 caractères"><small id="password-hint">Obligatoire pour un nouveau compte (4 caractères minimum)</small></label><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('user-modal')">Annuler</button><button type="submit" class="save"><i class="bi bi-check-lg"></i> Enregistrer</button></div></form></div></div>
<div class="users-modal-overlay" id="delete-modal"><div class="users-modal confirm-modal"><span class="warning-icon"><i class="bi bi-exclamation-triangle"></i></span><h3>Désactiver cet utilisateur ?</h3><p>Le compte <strong id="delete-name"></strong> ne pourra plus se connecter.</p><form method="POST" action="<?= BASE_URL ?>/utilisateurs"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" id="delete-id"><div class="modal-buttons"><button type="button" class="cancel" onclick="closeModal('delete-modal')">Annuler</button><button class="delete-confirm" type="submit">Désactiver</button></div></form></div></div>
<script>
let activeView='users';document.querySelectorAll('.view-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.view-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');activeView=b.dataset.view;document.getElementById('users-view').classList.toggle('hidden',activeView!=='users');document.getElementById('roles-view').classList.toggle('hidden',activeView!=='roles');filterRows()});
function filterRows(){const q=document.getElementById('user-search').value.toLowerCase().trim();let n=0;document.querySelectorAll('#'+activeView+'-view tbody tr[data-search]').forEach(r=>{const show=!q||r.dataset.search.includes(q);r.style.display=show?'':'none';if(show)n++});document.getElementById('result-count').textContent=n+' résultat(s)'}
function openUserModal(user=null){document.getElementById('user-action').value=user?'update':'create';document.getElementById('user-id').value=user?.id||'';document.getElementById('user-name').value=user?.nom_utilisateur||'';document.getElementById('user-role').value=user?.role||'ADMIN';document.getElementById('user-password').value='';document.getElementById('user-profile').value='';document.getElementById('user-password').required=!user;document.getElementById('user-modal-title').textContent=user?'Modifier l’utilisateur':'Ajouter un utilisateur';document.getElementById('password-hint').textContent=user?'Laissez vide pour conserver le mot de passe (4 caractères minimum si modifié)':'Obligatoire pour un nouveau compte (4 caractères minimum)';document.getElementById('profile-preview').innerHTML=user?.profil?`<img src="<?= BASE_URL ?>/${user.profil}" alt="Profil">`:'<i class="bi bi-camera"></i>';openModal('user-modal')}
function previewProfile(input){if(!input.files[0])return;const reader=new FileReader();reader.onload=e=>document.getElementById('profile-preview').innerHTML=`<img src="${e.target.result}" alt="Aperçu">`;reader.readAsDataURL(input.files[0])}
function openDeleteModal(id,name){document.getElementById('delete-id').value=id;document.getElementById('delete-name').textContent=name;openModal('delete-modal')}function openModal(id){document.getElementById(id).classList.add('show')}function closeModal(id){document.getElementById(id).classList.remove('show')}function toggleSidebar(){document.getElementById('dashboard-sidebar').classList.toggle('open');document.getElementById('mobile-overlay').classList.toggle('show')}setTimeout(()=>document.querySelector('.users-toast')?.remove(),4000);
</script></body></html>
